import type { TT } from "../content";
const D: Record<string, TT> = {
  "qr-code-generator": ["QR-Code-Generator mit Logo", "Erstelle einen herunterladbaren QR-Code für jeden Link oder Text, optional mit Logo.", "Kostenloser QR-Code-Generator mit Logo. Erstelle sofort einen QR-Code für jede URL oder jeden Text, ohne Anmeldung.", "Mit einem QR-Code öffnet man per Handykamera sofort einen Link, zeigt einen Text an oder verbindet sich mit dem WLAN. Dieser Generator erstellt aus jedem Text oder jeder URL einen hochauflösenden QR-Code und setzt auf Wunsch dein Logo in die Mitte.\n\nNützlich ist das für Druckmaterial und Verpackungen, für Restaurants mit Speisekarten-Link, für Veranstalter und für kleine Unternehmen, die Papier mit ihrer Website oder ihren Profilen verbinden.\n\nGib die URL oder den Text ein, die Vorschau aktualisiert sich sofort. Wähle Farben, stelle die Fehlerkorrektur ein (höher bei Logo) und lade das Ergebnis als PNG herunter.", [["Kann ich mein Logo in den QR-Code einfügen?", "Ja. Lade ein Bild hoch, es wird mit hoher Fehlerkorrektur in der Mitte platziert, damit der Code lesbar bleibt."], ["Läuft der QR-Code ab?", "Nein. Der Code enthält nur den Text oder die URL und funktioniert dauerhaft, solange das Ziel erreichbar ist."], ["Geht das auch für WLAN oder Kontakte?", "Ja. Du kannst beliebigen Text kodieren, auch WLAN- oder vCard-Formate, die Smartphones erkennen."], ["Werden meine Daten an einen Server gesendet?", "Nein. Der Code wird komplett in deinem Browser erzeugt."]]],
  "merge-pdf": ["PDF zusammenfügen (mehrere PDFs kombinieren)", "Mehrere PDF-Dateien in einer Datei zusammenführen, in der Reihenfolge deiner Wahl.", "Mehrere PDF-Dateien in einer Datei zusammenführen, in der Reihenfolge deiner Wahl.", "Wähle mehrere PDFs, ordne sie und lade ein einziges Dokument herunter. Alles läuft im Browser, deine Dateien werden nicht hochgeladen.\n\nPraktisch für Verträge, Rechnungen, Unterlagen oder Scans, die du als eine Datei versenden willst. Ändere die Reihenfolge, bevor du zusammenfügst.", [["Werden meine PDFs hochgeladen?", "Nein. Das Zusammenfügen passiert im Browser, die Dateien verlassen dein Gerät nicht."], ["Gibt es ein Limit für Dateien?", "Es gibt kein festes Limit. Praktisch hängt es vom Speicher deines Geräts ab."], ["Kann ich die Reihenfolge ändern?", "Ja, sortiere die Dateien vor dem Zusammenfügen neu."]]],
  "split-pdf": ["PDF seitenweise teilen", "Teile ein PDF in einzelne Seiten oder eigene Seitenbereiche.", "Teile ein PDF in einzelne Seiten oder eigene Seitenbereiche.", "Lade ein PDF hoch und wähle, wie es geteilt wird: jede Seite einzeln oder eigene Bereiche wie 1-3, 5. Das geschieht im Browser, die Datei wird nicht hochgeladen.\n\nNützlich, um ein Kapitel herauszuziehen, nur die nötigen Seiten zu versenden oder einen Sammel-Scan zu trennen. Die Ergebnisse erhältst du als ZIP.", [["Kann ich nur einzelne Seiten extrahieren?", "Ja, gib die gewünschten Bereiche an, etwa 1-3, 5, 8-10."], ["Wie lade ich mehrere Seiten herunter?", "Sie werden in einer ZIP-Datei gebündelt."], ["Wird mein PDF hochgeladen?", "Nein, alles läuft in deinem Browser."]]],
  "pdf-compressor": ["PDF-Komprimierer", "Verkleinere ein PDF, indem die Seitenbilder neu komprimiert werden.", "Verkleinere ein PDF, indem die Seitenbilder neu komprimiert werden.", "Wähle ein PDF und eine Kompressionsstufe und lade eine kleinere Version herunter. Es läuft im Browser, die Datei wird nicht hochgeladen.\n\nEin kleineres PDF lässt sich leichter per E-Mail senden oder in Formulare mit Größenlimit laden. Die Methode wandelt jede Seite in ein Bild um, daher ist der Text danach nicht mehr markierbar.", [["Geht Qualität verloren?", "Etwas, je nach Stufe. Probiere zuerst die mittlere Stufe."], ["Bleibt der Text markierbar?", "Nein. Die Seiten werden als komprimierte Bilder gespeichert."], ["Wird meine Datei hochgeladen?", "Nein, alles läuft in deinem Browser."]]],
  "jpg-to-pdf": ["JPG in PDF umwandeln", "Ein oder mehrere JPG-Bilder zu einem herunterladbaren PDF zusammenfassen.", "Ein oder mehrere JPG-Bilder zu einem herunterladbaren PDF zusammenfassen.", "Wähle deine JPG-Fotos, ordne sie und lade ein einziges PDF herunter. Alles läuft im Browser, die Bilder werden nicht hochgeladen.\n\nPraktisch, um Fotos von Dokumenten, Belegen oder Notizen in ein leicht versendbares PDF zu verwandeln. Die Reihenfolge der Bilder ist die Seitenreihenfolge.", [["Kann ich mehrere Bilder in ein PDF packen?", "Ja, jedes Bild wird eine Seite."], ["Werden meine Fotos hochgeladen?", "Nein, die Umwandlung passiert im Browser."], ["Ändert sich die Bildqualität?", "Die Bilder bleiben unverändert und werden nur auf Seiten platziert."]]],
  "pdf-to-jpg": ["PDF in JPG umwandeln", "Wandle jede Seite eines PDFs in ein herunterladbares JPG-Bild um.", "Wandle jede Seite eines PDFs in ein herunterladbares JPG-Bild um.", "Lade ein PDF hoch und erhalte pro Seite ein JPG-Bild in einer ZIP-Datei. Es läuft im Browser, die Datei wird nicht hochgeladen.\n\nPraktisch, um eine Seite als Bild zu teilen, in sozialen Netzwerken zu posten oder in eine Präsentation einzufügen. Die Qualität wählst du vor der Umwandlung.", [["Bekomme ich pro Seite ein Bild?", "Ja, jede Seite wird als JPG gespeichert."], ["Wird mein PDF hochgeladen?", "Nein, die Umwandlung passiert im Browser."], ["Kann ich die Qualität wählen?", "Ja, stelle sie vor der Umwandlung ein."]]],
  "percentage-calculator": ["Prozentrechner: Prozentwert, Prozentsatz, Erhöhung und Senkung", "Berechne Prozentwerte, prozentuale Veränderungen und den Anteil an einem Ganzen.", "Kostenloser Prozentrechner mit Rechenbeispielen. Berechne, wie viel Prozent X von Y ist, prozentuale Erhöhung oder Senkung und den Prozentwert einer Zahl, zum Beispiel 25/28 in Prozent.", "Prozente begegnen uns ständig: bei Rabatten, Trinkgeld, Gehaltserhöhungen oder Statistiken. Die passende Formel hängt davon ab, was gesucht ist. Dieser Rechner löst die drei häufigsten Aufgaben: wie viel Prozent eine Zahl von einer anderen ist, wie viel ein Prozentsatz einer Menge ergibt und um wie viel Prozent sich ein Wert erhöht oder verringert hat.\n\nWähle die Rechenart: „Wie viel sind X % von Y?“ (zum Beispiel 20 % von 150), „X sind wie viel Prozent von Y?“ (zum Beispiel 30 von 120) oder „Prozentuale Veränderung von X auf Y“ (zum Beispiel von 80 auf 100). Gib die Zahlen ein, und das Ergebnis erscheint sofort mit dem Rechenweg.\n\nEin häufiger Fehler ist die Annahme, dass sich eine Erhöhung um 50 % und eine Senkung um 50 % aufheben. Steigt 100 um 50 %, ergibt das 150. Sinkt 150 um 50 %, sind es 75 und nicht 100, weil sich jede Prozentangabe auf ihren eigenen Ausgangswert bezieht. Verwechsle auch Prozentpunkte nicht mit prozentualer Veränderung: Von 20 % auf 25 % Zinsen sind es 5 Prozentpunkte, aber eine relative Steigerung von 25 %. Zwei Rabatte hintereinander addieren sich außerdem nicht: 20 % und danach 10 % ergeben insgesamt 28 %, nicht 30 %.\n\nRechenbeispiele zum Nachprüfen mit dem Rechner:\n- Wie viel sind 15 % von 200? 200 × 0,15 = 30.\n- Wie viel sind 20 % von 85? 85 × 0,20 = 17.\n- 25 sind wie viel Prozent von 28? 25 ÷ 28 × 100 = 89,29 %, also sind 25/28 etwa 89,3 %.\n- 30 sind wie viel Prozent von 120? 30 ÷ 120 × 100 = 25 %.\n- Prozentuale Erhöhung von 80 auf 100: (100 − 80) ÷ 80 × 100 = 25 %.\n- Prozentuale Senkung von 50 auf 40: (50 − 40) ÷ 50 × 100 = 20 %.\n- Prozentualer Unterschied zwischen 40 und 60 (bezogen auf den Mittelwert 50): 20 ÷ 50 × 100 = 40 %.\n\nFormeln: Teil ÷ Ganzes × 100 ergibt den Prozentsatz. Der Prozentwert einer Zahl ist Zahl × Prozentsatz ÷ 100. Die prozentuale Veränderung ist (neu − alt) ÷ alt × 100. Um einen Bruch wie 25/28 in Prozent umzuwandeln, teile den Zähler durch den Nenner und multipliziere mit 100.", [["Warum führt eine Erhöhung um 50 % und danach eine Senkung um 50 % nicht zum Ausgangswert zurück?", "Weil sich jede Veränderung auf den aktuellen Wert bezieht und nicht auf den ursprünglichen. Die Rechnung ist deshalb nicht symmetrisch."], ["Was ist der Unterschied zwischen Prozentpunkten und prozentualer Veränderung?", "Prozentpunkte messen den absoluten Abstand zwischen zwei Prozentwerten (von 20 % auf 25 % sind es 5 Punkte). Die prozentuale Veränderung misst den relativen Unterschied (eine Steigerung um 25 %)."], ["Addieren sich aufeinanderfolgende Rabatte direkt?", "Nein. 20 % Rabatt und danach 10 % Rabatt ergeben insgesamt 28 %, nicht 30 %, weil der zweite Rabatt auf den bereits gesenkten Preis angewendet wird."], ["Kann ich damit Trinkgeld berechnen?", "Ja. Nutze „Wie viel sind X % von Y“ mit dem Rechnungsbetrag und dem gewünschten Trinkgeldsatz."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alle Berechnungen laufen sofort in deinem Browser."], ["Wie berechne ich 25/28 in Prozent?", "Teile 25 durch 28 und multipliziere mit 100. Das Ergebnis ist etwa 89,29 %."], ["Wie berechne ich eine prozentuale Erhöhung?", "Ziehe den alten Wert vom neuen ab, teile durch den alten Wert und multipliziere mit 100. Von 80 auf 100 sind das 25 %."], ["Wie finde ich heraus, wie viel Prozent eine Zahl von einer anderen ist?", "Teile den Teil durch das Ganze und multipliziere mit 100. Zum Beispiel sind 30 genau 25 % von 120."], ["Wie lautet die Formel für den prozentualen Unterschied?", "Teile den absoluten Unterschied durch den Mittelwert beider Zahlen und multipliziere mit 100. Für 40 und 60 ergibt das 40 %."]]],
  "age-calculator": ["Altersrechner: genaues Alter in Jahren, Monaten und Tagen", "Berechne dein genaues Alter in Jahren, Monaten und Tagen aus dem Geburtsdatum.", "Kostenloser Altersrechner. Zeigt dein genaues Alter in Jahren, Monaten und Tagen aus dem Geburtsdatum, die gelebten Tage oder dein Alter an einem beliebigen Datum.", "Das genaue Alter in Jahren, Monaten und Tagen zu berechnen, erfordert, unterschiedlich lange Monate und Schaltjahre zu berücksichtigen. Von Hand ist das aufwendiger, als es aussieht. Dieser Rechner zeigt sofort das genaue Alter oder die Zeitspanne zwischen zwei beliebigen Daten.\n\nGib ein Geburtsdatum (oder ein beliebiges Startdatum) und optional ein Datum „Stand“ ein (standardmäßig heute). Das Tool zeigt das Alter in Jahren, Monaten und Tagen sowie die Gesamtzahl der gelebten Tage und Wochen und den Wochentag der Geburt.\n\nSo wird das genaue Alter gezählt: Zuerst werden die Jahre subtrahiert, dann die Monate und zuletzt die Tage. Falls nötig, werden Tage aus dem Vormonat geborgt. Deshalb hat jemand, der am 31. Januar geboren ist, am 28. Februar eine andere Tageszahl als am 31. März. Wer am 29. Februar geboren ist, wird mit der tatsächlichen Länge jedes Monats gezählt.\n\nEin häufiger Fehler ist, das Geburtsjahr einfach vom aktuellen Jahr abzuziehen. Hat man in diesem Jahr noch nicht Geburtstag gehabt, ist das Ergebnis um ein Jahr zu hoch. Dieses Tool berücksichtigt Monat und Tag, nicht nur das Jahr.\n\nTypische Anwendungen: das genaue Alter eines Kindes in Monaten für ein Formular prüfen, feststellen, ob ein Mindestalter an einem Stichtag erreicht ist (Stichtag als „Stand“ eingeben), herausfinden, wie viele Tage man alt ist, und den Altersunterschied zweier Personen berechnen, indem man das Geburtsdatum der einen als Start und das der anderen als „Stand“ eingibt.\n\nZum Nachschlagen: Ein normales Jahr hat 365 Tage (52 Wochen und 1 Tag), ein Schaltjahr 366. Wer 30 Jahre alt ist, hat etwa 10.950 Tage plus 7 oder 8 Schalttage gelebt.", [["Werden Schaltjahre richtig berücksichtigt?", "Ja. Die Berechnung berücksichtigt Schaltjahre und unterschiedlich lange Monate, um das genaue Alter zu bestimmen."], ["Kann ich die Zeit zwischen zwei beliebigen Daten berechnen?", "Ja. Gib ein Startdatum und ein Enddatum an, um die genaue Dauer zwischen beiden zu erhalten."], ["Warum ist das einfache Abziehen der Jahre ungenau?", "Weil nicht geprüft wird, ob der Geburtstag in diesem Jahr schon war. Das Ergebnis kann je nach Datum um genau ein Jahr zu hoch sein."], ["Zeigt das Tool auch die Gesamtzahl der Tage oder Wochen?", "Ja. Neben der Aufteilung in Jahre, Monate und Tage werden auch die Gesamtzahlen der Tage und Wochen angezeigt."], ["Wird mein Geburtsdatum gespeichert?", "Nein. Die Berechnung läuft sofort und lokal in deinem Browser. Es werden keine persönlichen Daten gespeichert oder übertragen."], ["Wie berechne ich den Altersunterschied zwischen zwei Personen?", "Gib das Geburtsdatum der älteren Person als Startdatum und das der jüngeren als Datum „Stand“ ein. Das Ergebnis ist der Abstand in Jahren, Monaten und Tagen."], ["Wie finde ich mein Alter an einem bestimmten Datum heraus?", "Gib dein Geburtsdatum ein und setze bei „Stand“ das gewünschte Datum, etwa eine Bewerbungsfrist oder einen Termin."], ["Wie viele Tage bin ich alt?", "Gib dein Geburtsdatum ein. Das Tool zeigt die gelebten Tage neben der Aufteilung in Jahre, Monate und Tage."], ["Wie werden Geburten am 29. Februar behandelt?", "Die Berechnung nutzt die tatsächliche Länge jedes Monats, ein Geburtsdatum am 29. Februar wird also nach dem echten Kalender gezählt."]]],
  "bmi-calculator": ["BMI-Rechner (Body-Mass-Index)", "Berechne deinen Body-Mass-Index aus Körpergröße und Gewicht.", "Kostenloser BMI-Rechner. Berechne deinen Body-Mass-Index sofort aus Körpergröße und Gewicht, in metrischen oder imperialen Einheiten.", "Der Body-Mass-Index (BMI) ist ein weit verbreitetes Screening-Maß, das einschätzt, ob das Gewicht einer Person im Verhältnis zur Körpergröße in einem gesunden Bereich liegt. Er wird mit einer einfachen Formel aus zwei Zahlen berechnet. Dieser Rechner zeigt deinen BMI sofort und die passende Standardkategorie, mit metrischen oder imperialen Einheiten.\n\nWähle metrische Einheiten (Kilogramm und Zentimeter) oder imperiale (Pfund und Zoll oder Fuß), gib Größe und Gewicht ein, und der BMI wird mit der Standardformel berechnet: Gewicht in Kilogramm geteilt durch die Körpergröße in Metern zum Quadrat. Das Ergebnis erscheint zusammen mit den Kategorien der Weltgesundheitsorganisation: Untergewicht, Normalgewicht, Übergewicht und Adipositas.\n\nBeispiel: Eine Person mit 170 cm und 65 kg hat einen BMI von etwa 22,5. Das liegt nach WHO im Normalbereich (18,5–24,9).\n\nWichtig sind die Grenzen: Der BMI ist ein Screening-Instrument für Bevölkerungsgruppen, keine individuelle Diagnose. Er unterscheidet nicht zwischen Muskel- und Fettmasse, daher können sehr muskulöse Menschen, etwa Sportler, trotz wenig Körperfett und guter Gesundheit als übergewichtig oder adipös eingestuft werden. Alter, Geschlecht, Knochendichte und Fettverteilung bleiben ebenfalls unberücksichtigt. Nutze ihn als groben Anhaltspunkt und besprich deine Gesundheit mit einer Fachperson.\n\nTipp: Bist du Sportler, sehr muskulös, schwanger, älter oder fällst du aus anderen Gründen aus der untersuchten Gruppe, solltest du das Ergebnis vorsichtiger deuten und andere Werte wie Körperzusammensetzung, Fitness und Blutwerte mit einer Fachperson besprechen.", [["Ist der BMI ein genaues Maß für die individuelle Gesundheit?", "Er ist ein nützliches Screening-Instrument für Bevölkerungsgruppen, berücksichtigt aber weder Muskelmasse, Körperzusammensetzung, Alter noch Fettverteilung. Sprich immer mit einer medizinischen Fachperson."], ["Warum kann ein Sportler trotz guter Gesundheit einen hohen BMI haben?", "Weil Muskeln dichter sind als Fett: Sehr muskulöse Menschen wiegen im Verhältnis zur Größe mehr und haben einen höheren BMI, obwohl sie wenig Körperfett haben."], ["Wie lauten die BMI-Standardkategorien?", "Untergewicht (unter 18,5), Normalgewicht (18,5-24,9), Übergewicht (25-29,9) und Adipositas (ab 30) nach der WHO-Einteilung."], ["Gilt der BMI für Kinder genauso?", "Nein. Für Kinder und Jugendliche werden alters- und geschlechtsspezifische BMI-Perzentilkurven verwendet, nicht die hier genutzten Erwachsenenkategorien."], ["Werden meine Gesundheitsdaten gespeichert?", "Nein. Die Berechnung läuft sofort und lokal in deinem Browser. Es wird nichts gespeichert oder übertragen."]]],
  "loan-emi-calculator": ["Kreditrechner: monatliche Rate (EMI)", "Berechne monatliche Rate, Gesamtzinsen und Gesamtkosten für jeden Kredit.", "Berechne die monatliche Kreditrate (EMI), die Gesamtzinsen und die Gesamtkosten aus Kreditbetrag, Zinssatz und Laufzeit.", "Die EMI (gleichbleibende Monatsrate) ist der feste Betrag, den du jeden Monat zahlst, bis der Kredit abbezahlt ist. Sie enthält Zinsen und einen Teil der Tilgung. Gib Kreditbetrag, jährlichen Zinssatz und Laufzeit in Jahren ein, und der Rechner zeigt die monatliche Rate, den Gesamtbetrag und die Gesamtzinsen.\n\nDie Formel lautet EMI = P × r × (1 + r)^n / ((1 + r)^n − 1). Dabei ist P der Kreditbetrag, r der monatliche Zinssatz (Jahreszins geteilt durch 12 und durch 100) und n die Zahl der Monatsraten. Die ersten Raten bestehen überwiegend aus Zinsen, der Tilgungsanteil wächst mit der Zeit.\n\nNutze den Rechner, um Kreditangebote zu vergleichen, zu sehen, wie eine längere Laufzeit die Rate senkt, aber die Gesamtzinsen erhöht, oder um zu prüfen, was du dir leisten kannst. Bankgebühren, Versicherungen und variable Zinsen sind nicht enthalten. Das Ergebnis ist eine Schätzung, den endgültigen Betrag bestätigt dir dein Kreditgeber.", [["Wie wird die EMI berechnet?", "EMI = P × r × (1 + r)^n / ((1 + r)^n − 1), mit P als Kreditbetrag, r als monatlichem Zinssatz und n als Anzahl der Monate."], ["Senkt eine längere Laufzeit meine Rate?", "Ja, die monatliche Rate sinkt, aber du zahlst insgesamt mehr Zinsen, weil die Restschuld länger bestehen bleibt."], ["Sind Gebühren oder Versicherungen enthalten?", "Nein. Berücksichtigt werden nur Tilgung und Zinsen. Bearbeitungsgebühren und Versicherungen kommen separat hinzu."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "aspect-ratio-calculator": ["Seitenverhältnis-Rechner (16:9, 4:3 und mehr)", "Berechne proportionale Maße für jedes Seitenverhältnis.", "Kostenloser Seitenverhältnis-Rechner. Berechne proportionale Breite und Höhe für 16:9, 4:3, 1:1 und eigene Verhältnisse sofort.", "Das richtige Seitenverhältnis beim Skalieren von Bildern, Videos oder Designelementen verhindert Streckung und Verzerrung. Von Hand per Dreisatz ist das unter Zeitdruck leicht falsch. Dieser Rechner ermittelt sofort die fehlende Breite oder Höhe für ein Zielverhältnis oder das gekürzte Verhältnis aus zwei Maßen.\n\nEr hilft Videoeditoren und Content-Creatorn, die Projekte in 16:9 oder 9:16 anlegen, Designern, die Bilder proportional skalieren, und Entwicklern, die responsive Container mit festem Seitenverhältnis berechnen.\n\nWähle ein Standardverhältnis (16:9, 4:3, 1:1, 3:2, 21:9) oder gib ein eigenes ein, und trage eine bekannte Breite oder Höhe ein: Der Rechner zeigt das andere Maß. Du kannst auch zwei Maße eingeben, um ihr tatsächliches, gekürztes Verhältnis zu erhalten.\n\nBeispiel: Für ein 16:9-Videobild mit 1920 px Breite beträgt die richtige Höhe 1080 px. Und gibst du 2560×1440 in die Umkehrberechnung ein, ergibt sich 16:9, dasselbe Breitbildformat wie 1920×1080, nur mit höherer Auflösung.\n\nEin häufiger Fehler ist das Skalieren nach Augenmaß. Das führt oft zu leichter Streckung, die Betrachtern auffällt, auch wenn sie nicht sagen können, warum etwas „komisch aussieht“.\n\nTipp: Für responsive Webseiten mit festem Seitenverhältnis (etwa ein 16:9-Video-Container) nutze die CSS-Eigenschaft aspect-ratio (aspect-ratio: 16 / 9) statt der alten Padding-Prozent-Tricks. Das ist einfacher und besser lesbar.", [["Wie finde ich die Höhe, wenn ich nur Breite und Zielverhältnis kenne?", "Wähle oder gib das Verhältnis ein, trage die bekannte Breite ein, und der Rechner zeigt sofort die genaue Höhe."], ["Kann ich das Seitenverhältnis vorhandener Maße herausfinden?", "Ja. Gib Breite und Höhe in die Umkehrberechnung ein, um das gekürzte Verhältnis zu erhalten. 2560×1440 ergibt zum Beispiel 16:9."], ["Welche Seitenverhältnisse sind am häufigsten?", "16:9 (Breitbildvideo), 4:3 (älteres TV- und Fotoformat), 1:1 (quadratisch, in sozialen Netzwerken üblich), 9:16 (hochkant, Story-Format) und 21:9 (Ultrabreit, Kino)."], ["Warum ist ein gleichbleibendes Seitenverhältnis wichtig?", "Skalierst du ohne das ursprüngliche Verhältnis, wird der Inhalt gestreckt oder gestaucht, was meist auffällt und unprofessionell wirkt."], ["Kann ich das Ergebnis direkt in CSS verwenden?", "Ja. Nutze das berechnete Verhältnis mit der CSS-Eigenschaft aspect-ratio, um Proportionen in responsiven Layouts sauber festzulegen."]]],
  "mortgage-calculator": ["Baufinanzierungsrechner", "Schätze deine monatliche Rate für die Baufinanzierung inklusive Tilgung, Zinsen, Grundsteuer und Wohngebäudeversicherung.", "Schätze deine monatliche Rate für die Baufinanzierung inklusive Tilgung, Zinsen, Grundsteuer und Wohngebäudeversicherung.", "Eine Rate bei der Baufinanzierung besteht aus vier Teilen: Tilgung, Zinsen, Grundsteuer und Gebäudeversicherung. Dieser Rechner nimmt den Kaufpreis, dein Eigenkapital, den Zinssatz und die Laufzeit, addiert jährliche Steuer und Versicherung und zeigt die gesamten monatlichen Kosten sowie die Gesamtzinsen über die Laufzeit.\n\nMehr Eigenkapital senkt den Darlehensbetrag und die gezahlten Zinsen. Eine kürzere Laufzeit, etwa 15 statt 30 Jahre, erhöht die monatliche Rate, senkt die Gesamtzinsen aber deutlich. Probiere ein paar Kombinationen aus, um den Unterschied zu sehen.\n\nDas Ergebnis ist eine Schätzung. Kreditgeber können bei wenig Eigenkapital eine zusätzliche Versicherung verlangen, Hausgeld einrechnen oder den Zinssatz ändern. Nutze den Rechner zur Planung und frage danach ein verbindliches Angebot an.", [["Welchen Kaufpreis kann ich mir leisten?", "Als Faustregel sollten die Wohnkosten unter 28 % des monatlichen Bruttoeinkommens liegen. Gib verschiedene Preise ein, um zu sehen, wo die Rate landet."], ["Was ist in der Rate enthalten?", "Tilgung und Zinsen sowie die jährliche Grundsteuer und Versicherung, die du eingibst, geteilt durch 12."], ["Ist eine Restschuld- oder Hypothekenversicherung (PMI) enthalten?", "Nein. Trage sie im Feld für die Versicherung ein, falls dein Kreditgeber sie verlangt."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "compound-interest-calculator": ["Zinseszinsrechner", "Sieh, wie Ersparnisse oder Geldanlagen durch Zinseszins und monatliche Einzahlungen wachsen.", "Sieh, wie Ersparnisse oder Geldanlagen durch Zinseszins und monatliche Einzahlungen wachsen.", "Zinseszins bedeutet, dass du Zinsen auf deine früheren Zinsen erhältst und nicht nur auf den Anfangsbetrag. Über lange Zeiträume ist dieser Schneeballeffekt der Hauptgrund, früh anzufangen. Gib einen Startbetrag, eine monatliche Einzahlung, einen Jahreszins und die Anzahl der Jahre ein.\n\nDer Rechner wendet die gewählte Verzinsungshäufigkeit an (jährlich, vierteljährlich, monatlich oder täglich) und addiert deine Einzahlungen jeden Monat. Er zeigt den Endbetrag, wie viel du eingezahlt hast und wie viel aus Zinsen stammt.\n\nReale Renditen schwanken von Jahr zu Jahr, und Gebühren und Steuern mindern sie. Rechne zur Planung deshalb mit einem vorsichtigen Zinssatz. Die Zahl ist eine Prognose, keine Garantie.", [["Wie lautet die Zinseszinsformel?", "A = P(1 + r/n)^(nt) für eine einzelne Einzahlung. P ist das Kapital, r der Jahreszins, n die Verzinsungsperioden pro Jahr und t die Jahre."], ["Spielt häufigere Verzinsung eine Rolle?", "Ein wenig. Tägliche Verzinsung bringt bei gleichem Zinssatz etwas mehr als jährliche, aber Zinssatz und Zeit sind viel wichtiger."], ["Sind Steuern und Gebühren enthalten?", "Nein. Ziehe erwartete Gebühren und Steuern von deinem Zinssatz ab, um eine realistischere Schätzung zu bekommen."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "simple-interest-calculator": ["Einfacher Zinsrechner", "Berechne einfache Zinsen und den Gesamtbetrag für ein Kapital, einen Jahreszins und eine Anzahl von Jahren.", "Berechne einfache Zinsen und den Gesamtbetrag für ein Kapital, einen Jahreszins und eine Anzahl von Jahren.", "Einfache Zinsen werden nur auf das ursprüngliche Kapital berechnet, nicht auf bereits verdiente Zinsen. Die Formel lautet Z = K × p × t, wobei K das Kapital, p der Jahreszins als Dezimalzahl und t die Zeit in Jahren ist.\n\nSie werden bei kurzfristigen Krediten, manchen Autokrediten, Anleihen und im Mathematikunterricht verwendet. Gib Kapital, Jahreszins und Jahre ein, und du erhältst die Zinsen und den Gesamtbetrag, den du schuldest oder erhältst.\n\nWerden Zinsen dem Guthaben zugeschlagen und verzinsen sich selbst, nutze stattdessen den Zinseszinsrechner.", [["Wie lautet die Formel für einfache Zinsen?", "Z = K × p × t. Gesamtbetrag = K + Z."], ["Wie unterscheidet sie sich vom Zinseszins?", "Beim Zinseszins werden auch frühere Zinsen verzinst, daher wächst er über lange Zeiträume schneller."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "tip-calculator": ["Trinkgeldrechner", "Berechne das Trinkgeld und teile die Rechnung unter Freunden. Gib Rechnungsbetrag, Trinkgeldsatz und Personenzahl ein.", "Berechne das Trinkgeld und teile die Rechnung unter Freunden. Gib Rechnungsbetrag, Trinkgeldsatz und Personenzahl ein.", "Gib die Rechnungssumme ein, wähle einen Trinkgeldsatz und die Zahl der Personen, die sich die Rechnung teilen. Der Rechner zeigt das Trinkgeld, die Gesamtsumme und den Betrag pro Person.\n\nÜblich sind in den USA und Kanada 15 % bis 20 %. In vielen anderen Ländern ist die Bedienung bereits enthalten oder das Trinkgeld fällt klein aus. Schau also zuerst auf die Rechnung.\n\nSoll das Trinkgeld auf den Betrag vor Steuern berechnet werden, gib die Rechnung ohne Steuern ein. Unter Freunden ist es in Ordnung, pro Person auf einen glatten Betrag aufzurunden.", [["Wie viel Trinkgeld sollte ich geben?", "In den USA sind 15 % bis 20 % bei Bedienung am Tisch üblich. Die Bräuche unterscheiden sich von Land zu Land."], ["Berechnet man Trinkgeld vor oder nach Steuern?", "Viele berechnen es auf den Betrag vor Steuern. Beides ist in Ordnung."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "vat-calculator": ["Mehrwertsteuerrechner (MwSt. und Umsatzsteuer)", "Addiere oder entferne MwSt., GST oder Umsatzsteuer bei jedem Preis. Netto, Steuer und Brutto sofort.", "Addiere oder entferne MwSt., GST oder Umsatzsteuer bei jedem Preis. Netto, Steuer und Brutto sofort.", "Wähle, ob dein Betrag die Steuer schon enthält oder nicht. Um Steuer aufzuschlagen, multipliziert der Rechner den Nettopreis mit (1 + Satz). Um sie herauszurechnen, teilt er den Bruttopreis durch (1 + Satz). Das ist nicht dasselbe wie den Prozentsatz abzuziehen.\n\nStelle jeden Satz ein: 14 % (Mehrwertsteuer in Ägypten), 20 % (Großbritannien), 19 % (Deutschland), 5 % (Vereinigte Arabische Emirate) oder die Umsatzsteuer eines US-Bundesstaats. Das Tool zeigt Nettobetrag, Steuerbetrag und Bruttosumme.\n\nPrüfe immer, welcher Satz für dein Produkt und dein Land gilt, da einige Waren ermäßigte oder 0-Sätze haben.", [["Wie rechne ich die Mehrwertsteuer aus einem Preis heraus?", "Teile den Bruttopreis durch 1 + Steuersatz. Bei 20 % teilst du durch 1,2."], ["Warum nicht einfach 20 % vom Preis abziehen?", "Weil die Steuer auf den Nettopreis aufgeschlagen wurde. Sie sind also 20 % vom Netto, nicht vom Brutto."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "hourly-to-salary-calculator": ["Stundenlohn-Gehaltsrechner", "Rechne einen Stundenlohn in Jahres-, Monats-, Wochen- und Tagesverdienst um.", "Rechne einen Stundenlohn in Jahres-, Monats-, Wochen- und Tagesverdienst um.", "Gib deinen Stundenlohn, deine Wochenarbeitsstunden und die Arbeitswochen pro Jahr ein. Der Rechner multipliziert sie zu deinem jährlichen Bruttoverdienst und teilt ihn dann in Monats-, Wochen- und Tagesbeträge.\n\nEine Vollzeitstelle mit 40 Stunden über 52 Wochen ergibt 2.080 Stunden pro Jahr. Ziehe unbezahlte Wochen ab, wenn du unbezahlt freinimmst.\n\nDas sind Bruttobeträge vor Steuern und Abzügen. Dein Nettoverdienst liegt niedriger.", [["Wie viele Arbeitsstunden hat ein Jahr?", "Etwa 2.080 bei einer 40-Stunden-Woche und 52 Wochen."], ["Ist das Ergebnis vor oder nach Steuern?", "Vor Steuern. Es ist dein Bruttoverdienst."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "days-between-dates-calculator": ["Tage-zwischen-Daten-Rechner", "Zähle die Tage, Wochen, Monate und Werktage zwischen zwei Daten.", "Zähle die Tage, Wochen, Monate und Werktage zwischen zwei Daten.", "Wähle ein Start- und ein Enddatum, und der Rechner zeigt die Anzahl der Tage dazwischen, denselben Zeitraum in Wochen, in Jahren, Monaten und Tagen sowie die Anzahl der Werktage (Montag bis Freitag).\n\nNutze ihn für den Countdown bis zu einem Ereignis, für Kündigungsfristen, zur Projektdauer oder zur Betriebszugehörigkeit. Die Reihenfolge der Daten spielt keine Rolle.\n\nFeiertage werden bei den Werktagen nicht herausgerechnet.", [["Wird das Enddatum mitgezählt?", "Es wird die Differenz gezählt, das Enddatum zählt also nicht mit. Addiere einen Tag, wenn beide Tage mitzählen sollen."], ["Wie werden Monate gezählt?", "Nach Kalendermonaten, danach die verbleibenden Tage."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "date-calculator": ["Datumsrechner: Tage, Wochen und Monate addieren oder subtrahieren", "Addiere oder subtrahiere Tage, Wochen, Monate oder Jahre zu einem beliebigen Datum.", "Addiere oder subtrahiere Tage, Wochen, Monate oder Jahre zu einem beliebigen Datum.", "Wähle ein Startdatum, entscheide zwischen Addieren und Subtrahieren, gib eine Menge und eine Einheit ein, und der Rechner zeigt das Ergebnisdatum mit Wochentag.\n\nEr berücksichtigt Monatslängen und Schaltjahre. Nutze ihn für Fristen, Fälligkeitstermine, Garantien und Testzeiträume.\n\nWerktage und Feiertage werden nicht übersprungen.", [["Welches Datum ist in 90 Tagen?", "Setze das Startdatum auf heute, wähle Addieren, gib 90 ein und wähle die Einheit Tage."], ["Werden Schaltjahre berücksichtigt?", "Ja, er nutzt den Kalender deines Browsers."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "calorie-calculator": ["Kalorienrechner (Grundumsatz und Gesamtumsatz)", "Schätze deinen täglichen Kalorienbedarf zum Halten, Abnehmen oder Zunehmen mit der Mifflin-St-Jeor-Gleichung.", "Schätze deinen täglichen Kalorienbedarf zum Halten, Abnehmen oder Zunehmen mit der Mifflin-St-Jeor-Gleichung.", "Dein Grundumsatz ist die Energie, die dein Körper in Ruhe verbrennt. Multipliziert mit einem Aktivitätsfaktor ergibt er deinen Gesamtumsatz, also ungefähr die Kalorien, die du brauchst, um dein Gewicht zu halten.\n\nDieses Tool nutzt die Mifflin-St-Jeor-Gleichung. Gib Geschlecht, Alter, Größe, Gewicht und Aktivitätslevel ein. Ein Defizit von etwa 500 Kalorien pro Tag führt meist zu rund 0,5 kg Gewichtsverlust pro Woche, ein Überschuss von 500 zu einer Zunahme.\n\nDas ist eine Schätzung und keine medizinische Beratung. Unterschreite sichere Mindestmengen nicht ohne professionelle Begleitung.", [["Was ist der Grundumsatz?", "Die Kalorien, die dein Körper in Ruhe verbrennt, um dich am Leben zu halten."], ["Wie genau ist er?", "Bei den meisten Erwachsenen liegt er etwa 10 % daneben. Beobachte dein Gewicht zwei Wochen lang und passe an."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "ideal-weight-calculator": ["Idealgewichtsrechner", "Schätze dein Idealgewicht nach Größe und Geschlecht, mit dem gesunden BMI-Bereich.", "Schätze dein Idealgewicht nach Größe und Geschlecht, mit dem gesunden BMI-Bereich.", "Gib Größe und Geschlecht ein, um Schätzungen des Idealgewichts nach den Formeln von Devine und Robinson zu sehen, außerdem den Gewichtsbereich, der einem gesunden BMI von 18,5 bis 24,9 entspricht.\n\nDiese Formeln liefern einen groben Richtwert. Muskelmasse, Knochenbau und Alter verändern, was für einen Menschen gesund ist.\n\nNutze den BMI-Bereich als breitere Orientierung und sprich für persönliche Beratung mit einem Arzt.", [["Welche Formel ist die beste?", "Keine ist perfekt. Der BMI-Bereich ist eine breitere Orientierung als eine einzelne Zahl."], ["Ist der BMI bei Sportlern verlässlich?", "Nein. Muskeln wiegen mehr als Fett, daher können Sportler einen hohen BMI haben und trotzdem gesund sein."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "roi-calculator": ["ROI-Rechner (Kapitalrendite)", "Berechne Kapitalrendite, Gewinn und annualisierte Rendite für jede Geldanlage.", "Berechne Kapitalrendite, Gewinn und annualisierte Rendite für jede Geldanlage.", "Der ROI ist der Gewinn einer Investition geteilt durch ihre Kosten, als Prozentwert. Gib ein, was du investiert hast und den Endwert, und der Rechner zeigt Gewinn und ROI. Gibst du zusätzlich die Haltedauer in Jahren an, zeigt er auch die annualisierte Rendite.\n\nROI = (Endwert − Kosten) / Kosten × 100. Die annualisierte Rendite (CAGR) macht zwei Investitionen mit unterschiedlicher Haltedauer vergleichbar.\n\nDenke an Gebühren, Steuern und Inflation, die deine reale Rendite schmälern.", [["Was ist ein guter ROI?", "Das hängt von Anlageklasse und Risiko ab. Langfristige Aktienmarktrenditen liegen im Schnitt bei etwa 7 % bis 10 % pro Jahr vor Inflation."], ["Was ist der Unterschied zwischen ROI und CAGR?", "Der ROI ist die Gesamtrendite. Der CAGR ist die jährliche Rate, die sie erzeugen würde."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "cagr-calculator": ["CAGR-Rechner (durchschnittliche jährliche Wachstumsrate)", "Berechne die durchschnittliche jährliche Wachstumsrate aus Startwert, Endwert und Anzahl der Jahre.", "Berechne die durchschnittliche jährliche Wachstumsrate aus Startwert, Endwert und Anzahl der Jahre.", "Der CAGR ist die konstante jährliche Wachstumsrate, die einen Wert über einen Zeitraum vom Anfang zum Ende führen würde. Die Formel lautet (Endwert / Startwert)^(1 / Jahre) − 1.\n\nEr glättet Auf und Ab, damit du Investitionen, Umsatz oder Nutzerwachstum über verschiedene Zeiträume fair vergleichen kannst.\n\nDer CAGR zeigt keine Schwankungen. Zwei Investitionen können denselben CAGR, aber ein sehr unterschiedliches Risiko haben.", [["Wie berechne ich den CAGR?", "Teile den Endwert durch den Startwert, potenziere mit 1 geteilt durch die Jahre und ziehe 1 ab."], ["Kann der CAGR negativ sein?", "Ja, wenn der Endwert unter dem Startwert liegt."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "percentage-increase-calculator": ["Rechner für prozentuale Zunahme und Abnahme", "Finde die prozentuale Zunahme oder Abnahme zwischen zwei Zahlen.", "Finde die prozentuale Zunahme oder Abnahme zwischen zwei Zahlen.", "Gib den alten und den neuen Wert ein, um die prozentuale Veränderung zu erhalten. Ein positives Ergebnis ist eine Zunahme, ein negatives eine Abnahme. Die Formel lautet (neu − alt) / alt × 100.\n\nDas Tool zeigt auch den symmetrischen prozentualen Unterschied, der durch den Mittelwert beider Werte geteilt wird. Nutze ihn, wenn keiner der Werte klar der Ausgangspunkt ist.\n\nEine Zunahme um 50 % gefolgt von einer Abnahme um 50 % führt nicht zum Start zurück, weil sich jeder Prozentsatz auf eine andere Basis bezieht.", [["Wie berechne ich die prozentuale Veränderung?", "(neu − alt) / alt × 100."], ["Was ist der prozentuale Unterschied?", "Der Abstand zwischen zwei Werten geteilt durch ihren Mittelwert, genutzt, wenn es keine Bezugsgröße gibt."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "speed-distance-time-calculator": ["Geschwindigkeit-Strecke-Zeit-Rechner", "Berechne die Geschwindigkeit aus Strecke und Zeit, in km/h, mph und Lauftempo.", "Berechne die Geschwindigkeit aus Strecke und Zeit, in km/h, mph und Lauftempo.", "Geschwindigkeit ist Strecke geteilt durch Zeit. Gib eine Strecke in Kilometern und eine Zeit in Stunden ein, um die Durchschnittsgeschwindigkeit in km/h und mph sowie dein Tempo in Minuten pro Kilometer zu erhalten.\n\nDie Strecke erhältst du, indem du Geschwindigkeit mit Zeit multiplizierst. Die Zeit erhältst du, indem du die Strecke durch die Geschwindigkeit teilst. Nutze Dezimalstunden: 1 Stunde 30 Minuten sind 1,5.\n\nFür Läufer ist das Tempo die Zahl zum Vergleichen. Für Autofahrer hilft die Durchschnittsgeschwindigkeit bei der Schätzung der Ankunftszeit.", [["Wie rechne ich Minuten in Stunden um?", "Teile durch 60. 45 Minuten sind 0,75 Stunden."], ["Was ist das Tempo?", "Die Zeit, die man für einen Kilometer oder eine Meile braucht."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "pregnancy-due-date-calculator": ["Geburtstermin-Rechner", "Schätze deinen Geburtstermin und den Empfängnistag ab dem ersten Tag deiner letzten Periode.", "Schätze deinen Geburtstermin und den Empfängnistag ab dem ersten Tag deiner letzten Periode.", "Gib den ersten Tag deiner letzten Periode und deine übliche Zykluslänge ein. Der Rechner addiert 280 Tage (Naegele-Regel), angepasst an die Zykluslänge, um den Geburtstermin zu schätzen, und zeigt einen ungefähren Empfängnistag und deine aktuelle Woche.\n\nNur etwa 5 % der Babys kommen am errechneten Termin zur Welt. Die meisten kommen zwischen der 37. und 42. Woche. Ein früher Ultraschall liefert die genaueste Datierung.\n\nDieses Tool dient nur der Information. Folge dem Rat deiner Ärztin, deines Arztes oder deiner Hebamme.", [["Wie wird der Geburtstermin berechnet?", "280 Tage (40 Wochen) nach dem ersten Tag der letzten Periode."], ["Ist er genau?", "Es ist eine Schätzung. Die Datierung per Ultraschall ist genauer."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "fraction-calculator": ["Bruchrechner", "Addiere, subtrahiere, multipliziere und dividiere Brüche. Mit gekürztem Bruch, gemischter Zahl und Dezimalzahl.", "Addiere, subtrahiere, multipliziere und dividiere Brüche. Mit gekürztem Bruch, gemischter Zahl und Dezimalzahl.", "Gib zwei Brüche ein und wähle eine Rechenart. Der Rechner findet bei Bedarf einen gemeinsamen Nenner, kürzt das Ergebnis mit dem größten gemeinsamen Teiler und zeigt es als Bruch, gemischte Zahl und Dezimalzahl.\n\nZum Addieren oder Subtrahieren müssen die Nenner übereinstimmen, daher wird jeder Bruch zuerst umgewandelt. Beim Multiplizieren werden Zähler und Nenner multipliziert. Beim Dividieren multipliziert man mit dem Kehrwert des zweiten Bruchs.\n\nNutze ihn, um Hausaufgaben, Rezepte und Maße zu prüfen.", [["Wie addiere ich Brüche?", "Finde einen gemeinsamen Nenner, addiere die Zähler und kürze."], ["Wie dividiere ich Brüche?", "Drehe den zweiten Bruch um und multipliziere."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "average-calculator": ["Durchschnittsrechner (Mittelwert, Median, Modus)", "Füge eine Zahlenliste ein und erhalte Mittelwert, Median, Modus, Summe, Spannweite und Standardabweichung.", "Füge eine Zahlenliste ein und erhalte Mittelwert, Median, Modus, Summe, Spannweite und Standardabweichung.", "Füge Zahlen, getrennt durch Kommas, Leerzeichen oder Zeilenumbrüche, ein oder tippe sie. Der Rechner zeigt Anzahl, Summe, Mittelwert (Durchschnitt), Median (mittlerer Wert), Modus (häufigster Wert), Minimum, Maximum und die Stichproben-Standardabweichung.\n\nDer Mittelwert ist die Summe geteilt durch die Anzahl. Der Median ist weniger von Extremwerten beeinflusst und daher besser für Einkommen oder Preise. Die Standardabweichung zeigt, wie stark die Zahlen streuen.\n\nNicht numerische Einträge werden ignoriert.", [["Was ist der Unterschied zwischen Mittelwert und Median?", "Der Mittelwert ist der arithmetische Durchschnitt. Der Median ist der mittlere Wert nach dem Sortieren."], ["Ist die Standardabweichung die der Stichprobe oder der Grundgesamtheit?", "Die der Stichprobe (Division durch n − 1)."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "random-number-generator": ["Zufallszahlengenerator", "Erzeuge Zufallszahlen in jedem Bereich, mit oder ohne Wiederholung, mit der sicheren Zufallsquelle deines Browsers.", "Erzeuge Zufallszahlen in jedem Bereich, mit oder ohne Wiederholung, mit der sicheren Zufallsquelle deines Browsers.", "Lege Minimum und Maximum fest, wähle, wie viele Zahlen du willst, und klicke auf Erzeugen. Setze das Häkchen bei Keine Wiederholungen, um eindeutige Zahlen zu ziehen, wie Lottokugeln.\n\nDie Zahlen stammen aus dem kryptografischen Zufallsgenerator des Browsers, der sich für Spiele, Verlosungen und Stichproben eignet.\n\nFür offizielle Ziehungen oder Sicherheitsschlüssel befolge die Regeln deiner Organisation.", [["Ist es wirklich zufällig?", "Es nutzt crypto.getRandomValues, eine kryptografisch starke Quelle."], ["Kann ich eindeutige Zahlen bekommen?", "Ja, setze das Häkchen bei Keine Wiederholungen."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "dice-roller": ["Würfel und Münzwurf", "Wirf virtuelle Würfel (d4 bis d100) oder wirf eine Münze. Fair, sofort und mobil nutzbar.", "Wirf virtuelle Würfel (d4 bis d100) oder wirf eine Münze. Fair, sofort und mobil nutzbar.", "Wähle, wie viele Würfel und wie viele Seiten, und würfle. Das Tool zeigt jeden Würfel und die Summe. Es unterstützt d4, d6, d8, d10, d12, d20 und d100 für Brett- und Rollenspiele.\n\nDer Münzwurf-Button liefert Kopf oder Zahl mit gleicher Wahrscheinlichkeit.\n\nDie Würfe nutzen eine sichere Zufallsquelle und werden nicht gespeichert.", [["Sind die Würfe fair?", "Ja, jede Seite hat dieselbe Wahrscheinlichkeit."], ["Kann ich mehrere Würfel auf einmal werfen?", "Ja, bis zu 50 gleichzeitig."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "random-name-picker": ["Zufälliger Namensgenerator", "Ziehe einen Gewinner aus einer Namensliste oder mische die Liste. Ideal für Verlosungen, Klassen und Teams.", "Ziehe einen Gewinner aus einer Namensliste oder mische die Liste. Ideal für Verlosungen, Klassen und Teams.", "Füge einen Namen oder Eintrag pro Zeile ein. Klicke auf Gewinner ziehen, um zufällig einen auszuwählen, oder auf Mischen, um die Reihenfolge der Liste zufällig zu ordnen, etwa für Teams oder die Reihenfolge von Vorträgen.\n\nEs nutzt eine sichere Zufallsquelle, jeder Eintrag hat also dieselbe Chance.\n\nNimm bei öffentlichen Verlosungen den Bildschirm auf, damit die Teilnehmer die Ziehung nachprüfen können.", [["Ist die Auswahl fair?", "Ja, jede Zeile hat dieselbe Chance."], ["Kann ich mehr als einen ziehen?", "Klicke erneut auf Ziehen oder nutze Mischen und nimm die obersten Namen."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "stopwatch": ["Online-Stoppuhr", "Eine einfache Online-Stoppuhr mit Rundenzeiten. Läuft im Browser, ohne Installation.", "Eine einfache Online-Stoppuhr mit Rundenzeiten. Läuft im Browser, ohne Installation.", "Klicke auf Start, um die Zeit zu messen, und auf Pause, um sie anzuhalten. Mit Runde speicherst du Zwischenzeiten, während die Stoppuhr weiterläuft, und mit Zurücksetzen löschst du alles.\n\nDie Zeit wird von der Systemuhr gemessen und bleibt genau, auch wenn der Tab im Hintergrund langsam läuft.\n\nLasse die Seite beim Messen geöffnet.", [["Wie genau ist sie?", "Auf etwa eine Hundertstelsekunde, begrenzt durch dein Gerät."], ["Läuft sie weiter, wenn ich den Tab wechsle?", "Ja, sie berechnet die Zeit aus der Uhr neu, wenn du zurückkehrst."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "countdown-timer": ["Online-Countdown-Timer", "Stelle einen Countdown in Minuten ein. Ein Ton erklingt bei Ablauf, und die Zeit steht im Tab-Titel.", "Stelle einen Countdown in Minuten ein. Ein Ton erklingt bei Ablauf, und die Zeit steht im Tab-Titel.", "Gib die Minuten ein und klicke auf Start. Die Restzeit erscheint in großen Ziffern und im Titel des Browser-Tabs, sodass du in einem anderen Tab arbeiten kannst. Am Ende ertönt ein kurzer Piepton.\n\nNutze ihn zum Kochen, für Workouts, Präsentationen, Prüfungen und Lernphasen.\n\nLasse den Tab geöffnet und den Ton eingeschaltet.", [["Kann ich den Timer pausieren?", "Ja, klicke auf Pause und dann wieder auf Start, um fortzufahren."], ["Klingelt er auch, wenn der Tab im Hintergrund ist?", "Meistens ja, aber manche Browser begrenzen Audio im Hintergrund. Achte daher auf den Tab-Titel."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "pomodoro-timer": ["Pomodoro-Timer", "Ein Pomodoro-Timer mit 25-minütigen Fokusphasen und 5-minütigen Pausen.", "Ein Pomodoro-Timer mit 25-minütigen Fokusphasen und 5-minütigen Pausen.", "Die Pomodoro-Technik teilt Arbeit in konzentrierte 25-Minuten-Phasen mit 5-Minuten-Pausen. Klicke auf Start für eine Fokusphase. Wenn sie endet, ertönt ein Piepton, und der Timer wechselt zur Pause.\n\nNach vier Phasen folgt eine längere Pause von 15 bis 30 Minuten. Du kannst die Minuten jederzeit ändern.\n\nBeseitige Ablenkungen während einer Phase und notiere neue Aufgaben für später.", [["Was ist die Pomodoro-Technik?", "Eine Zeitmanagement-Methode von Francesco Cirillo mit 25-Minuten-Arbeitsblöcken und kurzen Pausen."], ["Kann ich die Dauer ändern?", "Ja, bearbeite das Minutenfeld."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "morse-code-translator": ["Morsecode-Übersetzer", "Übersetze Text in Morsecode und Morsecode in Text. Buchstaben, Zahlen und gängige Satzzeichen.", "Übersetze Text in Morsecode und Morsecode in Text. Buchstaben, Zahlen und gängige Satzzeichen.", "Wähle eine Richtung und tippe oder füge deinen Text ein. Buchstaben werden zu Punkten und Strichen, durch Leerzeichen getrennt, Wörter durch einen Schrägstrich. Zum Dekodieren füge Morsecode mit Leerzeichen zwischen den Buchstaben und einem Schrägstrich zwischen den Wörtern ein.\n\nDer Morsecode wurde in den 1830er und 1840er Jahren für die Telegrafie entwickelt und wird bis heute in der Luftfahrt, im Amateurfunk und als Notsignal verwendet. SOS sind drei Punkte, drei Striche, drei Punkte.\n\nUnbekannte Zeichen werden beim Kodieren übersprungen und beim Dekodieren als Fragezeichen angezeigt.", [["Wie schreibe ich SOS im Morsecode?", "... --- ..."], ["Wie trenne ich Wörter?", "Nutze einen Schrägstrich zwischen den Wörtern."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "text-to-binary": ["Text-zu-Binär-Konverter", "Wandle Text in Binärcode und Binärcode zurück in Text um. Unterstützt Unicode über UTF-8.", "Wandle Text in Binärcode und Binärcode zurück in Text um. Unterstützt Unicode über UTF-8.", "Gib Text ein und erhalte seine Binärdarstellung, bei ASCII ein 8-Bit-Byte pro Zeichen. Wechsle den Modus, um eine Binärfolge wieder in lesbaren Text zu dekodieren.\n\nText wird als UTF-8 kodiert, daher funktionieren auch Buchstaben mit Akzenten, Arabisch und Emojis, mit mehreren Bytes pro Zeichen.\n\nTrenne die Bytes beim Dekodieren durch Leerzeichen.", [["Wie lautet der Binärcode des Buchstabens A?", "01000001."], ["Werden Arabisch oder Emojis unterstützt?", "Ja, über UTF-8."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "roman-numeral-converter": ["Römische-Zahlen-Konverter", "Wandle Zahlen in römische Zahlen und römische Zahlen in Zahlen um (1 bis 3999).", "Wandle Zahlen in römische Zahlen und römische Zahlen in Zahlen um (1 bis 3999).", "Gib eine Zahl von 1 bis 3999 ein, um die römische Zahl zu erhalten, oder eine römische Zahl, um die Zahl zu erhalten. Das Tool nutzt die üblichen Subtraktionsregeln, etwa IV für 4 und CM für 900.\n\nRömische Zahlen verwenden die Buchstaben I, V, X, L, C, D und M für 1, 5, 10, 50, 100, 500 und 1000.\n\nZahlen über 3999 haben ohne erweiterte Schreibweise keine Standardform.", [["Was ist 2026 in römischen Zahlen?", "MMXXVI."], ["Warum liegt die Grenze bei 3999?", "Standard-Römerzahlen haben kein Symbol über M, und MMMM wird nicht verwendet."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "number-to-words-converter": ["Zahl-in-Worte-Konverter (Englisch)", "Wandle Zahlen in englische Worte um, für Schecks, Rechnungen und Texte. Unterstützt Dezimalzahlen und negative Zahlen.", "Wandle Zahlen in englische Worte um, für Schecks, Rechnungen und Texte. Unterstützt Dezimalzahlen und negative Zahlen.", "Gib eine Zahl wie 1234.56 ein und erhalte die englischen Worte: one thousand, two hundred and thirty-four point five six. Es unterstützt Zahlen bis in die Billionen, negative Zahlen und Dezimalzahlen.\n\nBeträge in Worten zu schreiben ist auf Schecks, in Verträgen und auf Rechnungen üblich, um Fälschungen zu verhindern.\n\nDie Schreibweise folgt dem britischen Stil, mit and nach den Hundertern.", [["Wie große Zahlen kann ich umwandeln?", "Bis 999 trillion (englische Zählweise, also knapp eine Trilliarde)."], ["Werden Dezimalzahlen unterstützt?", "Ja. Dezimalstellen werden Ziffer für Ziffer gelesen."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "text-repeater": ["Text-Wiederholer", "Wiederhole beliebigen Text oder Emojis oft mit einem eigenen Trennzeichen.", "Wiederhole beliebigen Text oder Emojis oft mit einem eigenen Trennzeichen.", "Gib deinen Text ein, wähle die Anzahl der Wiederholungen und ein Trennzeichen. Nutze \\n für einen Zeilenumbruch. Die Ausgabe lässt sich mit einem Klick kopieren.\n\nNützlich für Testdaten, Muster, Platzhalter und Social-Media-Beiträge.\n\nDas Limit liegt bei 10.000 Wiederholungen, damit dein Browser reaktionsfähig bleibt.", [["Was ist das Maximum?", "10.000 Wiederholungen."], ["Kann ich in neuen Zeilen wiederholen?", "Ja, nutze \\n als Trennzeichen."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "remove-punctuation": ["Satzzeichen aus Text entfernen", "Entferne Satzzeichen und Symbole aus jedem Text mit einem Klick. Funktioniert mit vielen Sprachen.", "Entferne Satzzeichen und Symbole aus jedem Text mit einem Klick. Funktioniert mit vielen Sprachen.", "Füge deinen Text ein, und alle Satzzeichen und Symbole werden entfernt, sodass Buchstaben, Zahlen und Leerzeichen übrig bleiben. Es funktioniert mit Unicode, Buchstaben mit Akzenten und nicht lateinische Buchstaben bleiben also erhalten.\n\nNützlich, um Text vor einer Analyse, Wortzählung, Keyword-Recherche oder für maschinelles Lernen zu bereinigen.\n\nMehrfache Leerzeichen werden zu einem zusammengefasst.", [["Entfernt es Apostrophe?", "Ja, alle Satzzeichen einschließlich Apostrophe."], ["Bleiben Buchstaben mit Akzenten erhalten?", "Ja."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "upside-down-text-generator": ["Generator für auf dem Kopf stehenden Text", "Drehe deinen Text mit speziellen Unicode-Zeichen auf den Kopf. Kopieren und überall einfügen.", "Drehe deinen Text mit speziellen Unicode-Zeichen auf den Kopf. Kopieren und überall einfügen.", "Gib Text ein und sieh ihn mit ähnlich aussehenden Unicode-Zeichen auf den Kopf gedreht und umgekehrt. Das Ergebnis lässt sich in Social-Media-Bios, Chats und Beiträge einfügen.\n\nDas funktioniert, weil Unicode Zeichen enthält, die gedrehten Buchstaben ähneln. Manche Zeichen haben keine gedrehte Version und bleiben unverändert.\n\nDas Aussehen hängt von der Schriftart der Plattform ab, in die du einfügst.", [["Wo kann ich ihn einfügen?", "Fast überall, wo Unicode-Text unterstützt wird, etwa Instagram, X und WhatsApp."], ["Warum sehen manche Buchstaben anders aus?", "Nicht jeder Buchstabe hat einen exakten gedrehten Unicode-Zwilling."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "word-frequency-counter": ["Wortfrequenz-Zähler", "Zähle, wie oft jedes Wort in deinem Text vorkommt. Nach Häufigkeit sortieren, nach Mindestanzahl filtern.", "Zähle, wie oft jedes Wort in deinem Text vorkommt. Nach Häufigkeit sortieren, nach Mindestanzahl filtern.", "Füge deinen Text ein und sieh jedes Wort mit Anzahl und Prozentwert, sortiert von häufig zu selten. Lege eine Mindestanzahl fest, um seltene Wörter auszublenden.\n\nAutoren nutzen ihn, um überstrapazierte Wörter zu finden, Studierende zur Textanalyse und SEO-Teams zur Prüfung der Keyword-Nutzung.\n\nDie Liste zeigt bis zu 100 Wörter. Wörter werden kleingeschrieben, Satzzeichen ignoriert.", [["Werden häufige Wörter wie \"the\" mitgezählt?", "Ja. Alle Wörter werden gezählt."], ["Funktioniert er auch in anderen Sprachen?", "Ja, er verarbeitet Unicode-Buchstaben."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "readability-score-checker": ["Lesbarkeitsprüfer (Flesch)", "Prüfe mit dem Flesch-Lesbarkeitsindex und der Klassenstufe, wie leicht dein englischer Text zu lesen ist.", "Prüfe mit dem Flesch-Lesbarkeitsindex und der Klassenstufe, wie leicht dein englischer Text zu lesen ist.", "Füge deinen Text ein, um den Flesch-Lesbarkeitsindex, eine geschätzte US-Klassenstufe, Wort- und Satzanzahl sowie die Lesezeit zu erhalten.\n\nHöhere Flesch-Werte sind leichter. Ein Wert von 60 bis 70 entspricht einfachem Englisch, das die meisten Erwachsenen verstehen. Kürzere Sätze und Wörter erhöhen den Wert.\n\nDie Silbenzählung ist bei englischen Wörtern ungefähr, nimm das Ergebnis also als Orientierung.", [["Was ist ein guter Flesch-Wert?", "60 bis 70 ist übliches einfaches Englisch. Webinhalte streben oft 60 oder mehr an."], ["Funktioniert es für Arabisch oder andere Sprachen?", "Nein. Die Formel ist für Englisch gedacht."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "number-base-converter": ["Zahlensystem-Umrechner (binär, oktal, dezimal, hexadezimal)", "Rechne Zahlen zwischen Binär-, Oktal-, Dezimal- und Hexadezimalsystem um.", "Rechne Zahlen zwischen Binär-, Oktal-, Dezimal- und Hexadezimalsystem um.", "Gib eine Zahl ein und wähle ihre Basis. Der Umrechner zeigt denselben Wert binär (Basis 2), oktal (Basis 8), dezimal (Basis 10) und hexadezimal (Basis 16). Sehr große Zahlen werden über Big Integers unterstützt.\n\nProgrammierer nutzen Hexadezimal für Farben, Speicheradressen und Bitmasken, Binär, um einzelne Bits zu sehen.\n\nDie Ziffern müssen für die gewählte Basis gültig sein, die 2 ist also im Binärsystem ungültig.", [["Wie wandle ich binär in dezimal um?", "Wähle Basis 2, gib die Binärzahl ein und lies das Dezimalergebnis ab."], ["Wird bei Hex zwischen Groß- und Kleinschreibung unterschieden?", "Nein."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "json-minifier": ["JSON-Minifier", "Minimiere JSON, indem Leerzeichen und Zeilenumbrüche entfernt werden. Prüft dein JSON gleichzeitig.", "Minimiere JSON, indem Leerzeichen und Zeilenumbrüche entfernt werden. Prüft dein JSON gleichzeitig.", "Füge formatiertes JSON ein und erhalte eine kompakte einzeilige Version ohne unnötige Leerzeichen. Das verringert die Größe von API-Nutzdaten und Konfigurationsdateien.\n\nDas Tool analysiert dein JSON zuerst, daher zeigt ungültige Eingabe einen Fehler an, statt defekte Ausgabe zu erzeugen.\n\nDas Minimieren ändert die Daten nicht, nur ihre Formatierung. Für das Gegenteil nutze den JSON-Formatierer.", [["Ändert das Minimieren meine Daten?", "Nein, es werden nur Leerzeichen entfernt."], ["Was, wenn mein JSON ungültig ist?", "Du siehst eine Fehlermeldung. Korrigiere zuerst die Syntax."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "sort-lines-alphabetically": ["Zeilen alphabetisch sortieren", "Sortiere Textzeilen von A bis Z, Z bis A, nach Zahl oder Länge, kehre die Reihenfolge um oder mische sie.", "Sortiere Textzeilen von A bis Z, Z bis A, nach Zahl oder Länge, kehre die Reihenfolge um oder mische sie.", "Füge eine Liste mit einem Eintrag pro Zeile ein und wähle einen Sortiermodus: A bis Z, Z bis A, numerisch, nach Länge, umgekehrt oder zufällig gemischt.\n\nDie alphabetische Sortierung nutzt einen sprachbewussten Vergleich, sodass Buchstaben mit Akzenten sinnvoll einsortiert werden. Die numerische Sortierung liest die Zahl am Anfang jeder Zeile.\n\nNutze sie für Namen, Keywords, URLs, To-do-Einträge und Datenbereinigung.", [["Wird zwischen Groß- und Kleinschreibung unterschieden?", "Nein, A und a werden zusammen sortiert."], ["Kann ich Zahlen richtig sortieren?", "Ja, wähle Numerisch, damit 10 nach 9 kommt."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "text-to-pdf": ["Text-zu-PDF-Konverter", "Erstelle aus reinem Text ein herunterladbares PDF im Browser. Ohne Upload, ohne Anmeldung.", "Erstelle aus reinem Text ein herunterladbares PDF im Browser. Ohne Upload, ohne Anmeldung.", "Gib Text ein oder füge ihn ein, wähle einen Dateinamen und klicke auf PDF herunterladen. Das Tool setzt den Text auf A4-Seiten mit Rändern, bricht lange Zeilen um und beginnt automatisch neue Seiten.\n\nDas PDF wird in deinem Browser mit einer PDF-Bibliothek erstellt, dein Text wird also nie auf einen Server hochgeladen.\n\nDie Standardschrift unterstützt lateinische Zeichen. Andere Schriften werden durch Fragezeichen ersetzt, nutze für Arabisch oder Chinesisch daher ein vollständiges Textverarbeitungsprogramm.", [["Wird mein Text hochgeladen?", "Nein. Er wird lokal erstellt."], ["Wird Arabisch unterstützt?", "Noch nicht. Nur lateinische Zeichen."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
  "time-zone-converter": ["Zeitzonen-Umrechner", "Rechne Datum und Uhrzeit gleichzeitig zwischen 25 wichtigen Zeitzonen um.", "Rechne Datum und Uhrzeit gleichzeitig zwischen 25 wichtigen Zeitzonen um.", "Wähle Datum und Uhrzeit, wähle die zugehörige Zeitzone und sieh denselben Zeitpunkt in 25 wichtigen Zeitzonen, darunter New York, London, Kairo, Dubai, Mumbai, Tokio und Sydney.\n\nEr nutzt die Zeitzonendatenbank deines Browsers, Sommerzeitwechsel werden für das gewählte Datum also berücksichtigt.\n\nNutze ihn, um Meetings und Anrufe über Ländergrenzen hinweg zu planen.", [["Werden Sommerzeitwechsel berücksichtigt?", "Ja, für das Datum, das du wählst."], ["Kann ich weitere Zonen hinzufügen?", "Die Liste deckt die gängigsten ab."], ["Werden meine Daten an einen Server gesendet?", "Nein. Alles läuft in deinem Browser. Nichts, was du eingibst, wird hochgeladen oder gespeichert."]]],
};
